import {
    ITUNES_STOREFRONTS, METADATA_LOOKUP_JOB_LIMITS as JOB, METADATA_LOOKUP_LIMITS,
    type ItunesCollection, type ItunesSearchResult, type ItunesStorefront, type ItunesTrack, type MusicBrainzRelease, type MusicBrainzTrack
} from './lookupContract';
import { itunesArtworkAddress, itunesStorefrontsForBarcode, itunesStorefrontsForText } from './iTunesSearchClient';
import { itunesArtworkUrl } from './itunesArtworkClient';
import { cleanLookupTerm, isPlaceholderCredit, normalizeGtin, normalizeItunesId } from './lookupIdentifiers';
import { isFallbackLookupQuery, type PlannedLookupQuery } from './lookupQueryPlanner';
import { lookupTrackCountPlausible, type LocalFileEvidence } from './lookupRanking';
import { musicBrainzLuceneQuery } from './musicBrainzClient';
import type { MetadataLookupRecord, StoredLookupCandidate } from './metadataLookupRecord';

/**
 * The iTunes fallback stage of a lookup run and its MusicBrainz bridge (pure; lookupRunStep.ts sends the requests). It starts only
 * when MusicBrainz returned no matching candidate, from the run's own planned queries: at most two UPC lookups of a valid embedded
 * barcode (storefronts by GS1 prefix, stopping at the first that answers a collection), then the first text search in at most three
 * storefronts chosen by script. At most four plausible results are kept (a collection whose track count can equal the files, a song
 * whose duration matches a single file), each with the title and artist every storefront showed. Their name pairs are searched again
 * in MusicBrainz (at most four bridge searches, names that differ from the searched text first, ` - Single`/` - EP` dropped from a
 * collection title, never respelled). A result whose bridge found a MusicBrainz release is evidence only; any other result is
 * resolved through a collection lookup (at most four; so a song's own collection name, which may be a box set's sub-album, is never
 * the album) and becomes an iTunes-only candidate (incomplete when that lookup gave fewer songs than the collection has), marked by
 * why it was not checked: `noRelease`, `unavailable` (MusicBrainz stayed unavailable through its automatic retries) or `notRun` (the
 * bridge was refused, could not be built or was over its bound). Every function is total on another release's stored shape. Owner
 * rules: docs/business-rules.md (Administrator Metadata Lookup).
 */
export type PlannedItunesRequest =
    | { kind: 'itunesUpc'; barcode: string; storefront: ItunesStorefront }
    | { kind: 'itunesSearch'; term: string; entity: 'album' | 'song'; storefront: ItunesStorefront };
/** One storefront's names of a result: a song's track name or a collection's name, and its single artist string. */
export type LookupItunesName = { storefront: ItunesStorefront; title: string; artist: string };
/**
 * One kept iTunes result. `bridge` is pending until the bridge ends; `collection` is the collection lookup of a result that becomes
 * a candidate (`notNeeded` for a bridged one or a repeat of another result's collection). `unbridged`: some name pair of it was not
 * searched (it could not be built or was over the bridge bound).
 */
export type LookupItunesItem = {
    key: string; kind: 'song' | 'collection'; collectionId: string; names: LookupItunesName[]; barcode: string | null;
    bridge: 'pending' | 'found' | 'noRelease' | 'unavailable' | 'notRun';
    collection: 'notNeeded' | 'pending' | 'fetched' | 'missing' | 'failed' | 'skipped';
    unbridged?: true;
};
/** A bridge search and the results whose names it searches. */
export type LookupItunesBridgeQuery = PlannedLookupQuery & { itemKeys: string[] };
/**
 * A run's iTunes stage. `reason`: MusicBrainz answered without a matching candidate, or its searches stayed unavailable. `text` is
 * the folded release or recording text the term came from (null for a barcode-only run). `complete` turns false when a plausible
 * result was left out (the result or candidate bound, or a collection lookup iTunes never answered); the run's comparison is then
 * partial.
 */
export type LookupItunesStage = {
    reason: 'noMatch' | 'searchUnavailable'; text: string | null;
    requests: PlannedItunesRequest[]; requestIndex: number; items: LookupItunesItem[];
    bridge: LookupItunesBridgeQuery[] | null; bridgeIndex: number; bridgeOutcomes: ('found' | 'none' | 'refused' | 'unsent')[];
    state: 'running' | 'answered' | 'unavailable'; complete: boolean; finalized: boolean;
};
/** The next iTunes-stage request: an iTunes search or UPC lookup, a bridge search, or a collection lookup. */
export type LookupItunesAction =
    | { kind: 'itunes'; index: number; request: PlannedItunesRequest }
    | { kind: 'bridge'; index: number; query: PlannedLookupQuery }
    | { kind: 'itunesCollection'; itemKey: string; collectionId: string; storefront: ItunesStorefront };

const isRecord = (value: unknown): value is Record<string, any> => Boolean(value) && typeof value === 'object' && !Array.isArray(value);
const fold = (value: string) => value.normalize('NFC').trim().toLowerCase();
const term = (value: unknown): string | null => { try { return cleanLookupTerm(value, METADATA_LOOKUP_LIMITS.termLength); } catch { return null; } };
const storefront = (value: unknown): value is ItunesStorefront => (ITUNES_STOREFRONTS as readonly unknown[]).includes(value);
const canonicalQuery = (query: PlannedLookupQuery) => {
    try { return query.kind === 'musicBrainzReleaseSearch' || query.kind === 'musicBrainzRecordingSearch' ? `${query.kind} ${musicBrainzLuceneQuery(query.query)}` : null; }
    catch { return null; }
};

/** The run's first non-fallback text search: its iTunes term (text and credited artist, never a label), entity and folded text. */
function itunesTextSearch(queries: readonly Record<string, any>[]): { term: string; entity: 'album' | 'song'; text: string } | null {
    const query = queries.find(item => !isFallbackLookupQuery(item) && isRecord(item.query)
        && ((item.kind === 'musicBrainzReleaseSearch' && (item.basis === 'albumText' || item.basis === 'folder')) || (item.kind === 'musicBrainzRecordingSearch' && item.basis === 'songText')));
    if (!query) return null;
    const text = term(query.kind === 'musicBrainzRecordingSearch' ? query.query.recording : query.query.release);
    if (!text) return null;
    const artist = typeof query.query.artist === 'string' ? term(query.query.artist) : null;
    return { term: (artist && term(`${text} ${artist}`)) || text, entity: query.kind === 'musicBrainzRecordingSearch' ? 'song' : 'album', text: fold(text) };
}

/**
 * The iTunes requests of a run, derived from its stored planned queries (so a manual retry repeats them): UPC lookups of its valid
 * barcode, then its first text search in each storefront its script chooses. A run planned only from a release ID or an ISRC, or
 * from malformed queries, has none.
 */
export function itunesRequestsFor(queries: readonly unknown[]): PlannedItunesRequest[] {
    const list = (Array.isArray(queries) ? queries : []).filter(isRecord), requests: PlannedItunesRequest[] = [];
    const barcode = list.find(item => item.kind === 'musicBrainzReleaseSearch' && item.basis === 'barcode' && isRecord(item.query));
    const gtin = barcode ? normalizeGtin(barcode.query.barcode) : null;
    if (gtin) for (const at of itunesStorefrontsForBarcode(gtin).slice(0, JOB.itunesUpcLookups)) requests.push({ kind: 'itunesUpc', barcode: gtin.digits, storefront: at });
    const text = itunesTextSearch(list);
    if (text) for (const at of itunesStorefrontsForText(text.term).slice(0, JOB.itunesSearches)) requests.push({ kind: 'itunesSearch', term: text.term, entity: text.entity, storefront: at });
    return requests;
}

/** A new stage for the run's queries, or null when they give no iTunes request. */
export function startItunesStage(queries: readonly unknown[], reason: LookupItunesStage['reason']): LookupItunesStage | null {
    const requests = itunesRequestsFor(queries);
    if (!requests.length) return null;
    const text = itunesTextSearch((Array.isArray(queries) ? queries : []).filter(isRecord))?.text ?? null;
    return { reason, text, requests, requestIndex: 0, items: [], bridge: null, bridgeIndex: 0, bridgeOutcomes: [], state: 'running', complete: true, finalized: false };
}

const itemStates = { bridge: ['pending', 'found', 'noRelease', 'unavailable', 'notRun'], collection: ['notNeeded', 'pending', 'fetched', 'missing', 'failed', 'skipped'] } as const;
/** A stored request, item or bridge query this release can use; anything else is dropped. */
function storedRequest(raw: unknown): PlannedItunesRequest | null {
    if (!isRecord(raw) || !storefront(raw.storefront)) return null;
    if (raw.kind === 'itunesUpc') { const gtin = normalizeGtin(raw.barcode); return gtin ? { kind: 'itunesUpc', barcode: gtin.digits, storefront: raw.storefront } : null; }
    const text = raw.kind === 'itunesSearch' ? term(raw.term) : null;
    return text && (raw.entity === 'album' || raw.entity === 'song') ? { kind: 'itunesSearch', term: text, entity: raw.entity, storefront: raw.storefront } : null;
}
function storedItem(raw: unknown): LookupItunesItem | null {
    if (!isRecord(raw) || typeof raw.key !== 'string' || (raw.kind !== 'song' && raw.kind !== 'collection')
        || !(itemStates.bridge as readonly unknown[]).includes(raw.bridge) || !(itemStates.collection as readonly unknown[]).includes(raw.collection)) return null;
    const names = (Array.isArray(raw.names) ? raw.names : []).filter((name: unknown): name is LookupItunesName => isRecord(name) && storefront(name.storefront)
        && typeof name.title === 'string' && typeof name.artist === 'string' && name.title.length <= METADATA_LOOKUP_LIMITS.textLength && name.artist.length <= METADATA_LOOKUP_LIMITS.textLength)
        .slice(0, ITUNES_STOREFRONTS.length);
    const collectionId = normalizeItunesId(raw.collectionId);
    if (!names.length || !collectionId) return null;
    return { key: raw.key, kind: raw.kind, collectionId, names, barcode: normalizeGtin(raw.barcode)?.digits ?? null, bridge: raw.bridge, collection: raw.collection,
        ...(raw.unbridged === true ? { unbridged: true as const } : {}) };
}
/**
 * The stored stage as this release reads it, or null when there is none or it is unreadable (another release's shape): requests,
 * items and bridge queries it cannot use are dropped, and indexes are clamped.
 */
export function storedItunesStage(raw: unknown): LookupItunesStage | null {
    if (!isRecord(raw) || (raw.reason !== 'noMatch' && raw.reason !== 'searchUnavailable') || !['running', 'answered', 'unavailable'].includes(raw.state)) return null;
    const requests = (Array.isArray(raw.requests) ? raw.requests : []).map(storedRequest).filter((request): request is PlannedItunesRequest => request !== null);
    const items = (Array.isArray(raw.items) ? raw.items : []).map(storedItem).filter((item): item is LookupItunesItem => item !== null).slice(0, JOB.itunesItems);
    const bridge = Array.isArray(raw.bridge) ? raw.bridge.filter((query: unknown): query is LookupItunesBridgeQuery => isRecord(query) && Array.isArray(query.itemKeys)
        && query.itemKeys.every((key: unknown) => typeof key === 'string') && canonicalQuery(query as PlannedLookupQuery) !== null).slice(0, JOB.bridgeSearches) : null;
    const outcomes = bridge ? bridge.map((_query, at) => ['found', 'none', 'refused', 'unsent'].includes(raw.bridgeOutcomes?.[at]) ? raw.bridgeOutcomes[at] : 'unsent') : [];
    const index = (value: unknown, max: number) => Number.isSafeInteger(value) && (value as number) >= 0 ? Math.min(value as number, max) : 0;
    return { reason: raw.reason, text: typeof raw.text === 'string' ? raw.text : null, requests, requestIndex: index(raw.requestIndex, requests.length), items,
        bridge, bridgeIndex: index(raw.bridgeIndex, bridge?.length ?? 0), bridgeOutcomes: outcomes, state: raw.state, complete: raw.complete === true, finalized: raw.finalized === true };
}

/** Whether a song's duration can match the import's only file: always, unless both durations are known and differ beyond the tolerance. */
const durationPlausible = (song: ItunesTrack, files: readonly LocalFileEvidence[]) => {
    const file = files.length === 1 ? files[0] : null;
    if (!file || file.durationMs === null || song.trackTimeMillis === null || song.trackTimeMillis <= 0) return true;
    return Math.abs(file.durationMs - song.trackTimeMillis) <= METADATA_LOOKUP_LIMITS.durationToleranceMs + file.durationPrecisionMs;
};
/** The plausible results of one answer in answer order: collections by track count, songs by duration. */
function answerItems(request: PlannedItunesRequest, result: ItunesSearchResult, files: readonly LocalFileEvidence[]): LookupItunesItem[] {
    const base = { bridge: 'pending' as const, collection: 'notNeeded' as const };
    if (request.kind === 'itunesSearch' && request.entity === 'song') {
        return result.tracks.filter(song => normalizeItunesId(song.trackId) && normalizeItunesId(song.collectionId) && durationPlausible(song, files)).map(song => ({
            ...base, key: `song:${song.trackId}`, kind: 'song' as const, collectionId: song.collectionId, barcode: null,
            names: [{ storefront: request.storefront, title: song.trackName, artist: song.artistName }] }));
    }
    return result.collections.filter(collection => normalizeItunesId(collection.collectionId) && lookupTrackCountPlausible(collection.trackCount, files.length)).map(collection => ({
        ...base, key: `collection:${collection.collectionId}`, kind: 'collection' as const, collectionId: collection.collectionId,
        barcode: request.kind === 'itunesUpc' ? request.barcode : null, names: [{ storefront: request.storefront, title: collection.collectionName, artist: collection.artistName }] }));
}

/**
 * Stores the answer to the stage's current request `index` (null: no such release): its plausible results join the kept ones (a
 * result already kept gains this storefront's names, once per storefront), up to the result bound, beyond which a plausible result
 * makes the stage incomplete. A UPC lookup that answers a collection ends the UPC lookups. A full search page does not make the
 * stage incomplete: iTunes reports no total.
 */
export function recordItunesAnswer(stage: LookupItunesStage, index: number, result: ItunesSearchResult | null, files: readonly LocalFileEvidence[]): LookupItunesStage {
    if (index !== stage.requestIndex || index >= stage.requests.length) return stage;
    const request = stage.requests[index], items = [...stage.items];
    let complete = stage.complete, requestIndex = index + 1;
    for (const item of result ? answerItems(request, result, files) : []) {
        const at = items.findIndex(existing => existing.key === item.key);
        if (at >= 0) {
            if (!items[at].names.some(name => name.storefront === request.storefront)) items[at] = { ...items[at], names: [...items[at].names, ...item.names] };
        } else if (items.length < JOB.itunesItems) items.push(item);
        else complete = false;
    }
    if (request.kind === 'itunesUpc' && result?.collections.length) while (stage.requests[requestIndex]?.kind === 'itunesUpc') requestIndex++;
    return { ...stage, items, complete, requestIndex };
}

/** A refused request (its input failed a format check) is skipped. */
export const skipItunesRequest = (stage: LookupItunesStage, index: number): LookupItunesStage =>
    index === stage.requestIndex && index < stage.requests.length ? { ...stage, requestIndex: index + 1 } : stage;

/** A collection title as MusicBrainz names the release: only a trailing ` - Single` or ` - EP` is dropped. */
export const itunesCollectionTitle = (name: string): string => name.replace(/ - (?:Single|EP)$/u, '');

/** The bridge search of one name pair: a recording search for a song, a release search for a collection; null when it cannot be built. */
function bridgeQuery(kind: LookupItunesItem['kind'], name: LookupItunesName): PlannedLookupQuery | null {
    const title = term(kind === 'collection' ? itunesCollectionTitle(name.title) : name.title);
    const artist = !isPlaceholderCredit(name.artist) ? term(name.artist) : null;
    if (!title) return null;
    const query: PlannedLookupQuery = kind === 'song'
        ? { kind: 'musicBrainzRecordingSearch', query: { recording: title, ...(artist ? { artist } : {}) }, basis: 'songText' }
        : { kind: 'musicBrainzReleaseSearch', query: { release: title, ...(artist ? { artist } : {}) }, basis: 'albumText' };
    return canonicalQuery(query) ? query : null;
}

/**
 * Plans the bridge once the iTunes requests are done: one search per distinct name pair of each result (a placeholder artist left
 * out), the pairs whose title differs from the searched text first (the Japanese title of a romanized search, or the reverse),
 * equal searches (ignoring case) merged, at most `bridgeSearches`. A pair that cannot be built or is over the bound marks its result `unbridged`.
 * With MusicBrainz already exhausted there is no bridge, and every result is unavailable when the bridge ends.
 */
export function planItunesBridge(stage: LookupItunesStage, musicBrainzExhausted: boolean): LookupItunesStage {
    if (stage.bridge !== null) return stage;
    if (musicBrainzExhausted) return { ...stage, bridge: [], bridgeIndex: 0, bridgeOutcomes: [] };
    const pairs: { itemKey: string; query: PlannedLookupQuery; differs: boolean }[] = [], unbridged = new Set<string>();
    for (const item of stage.items) {
        const seen = new Set<string>();
        for (const name of item.names) {
            const pair = `${fold(name.title)}\u0000${fold(name.artist)}`;
            if (seen.has(pair)) continue;
            seen.add(pair);
            const query = bridgeQuery(item.kind, name);
            if (!query) { unbridged.add(item.key); continue; }
            const title = fold(item.kind === 'collection' ? itunesCollectionTitle(name.title) : name.title);
            pairs.push({ itemKey: item.key, query, differs: stage.text === null || title !== stage.text });
        }
    }
    const bridge: LookupItunesBridgeQuery[] = [], keys: string[] = [];
    for (const pair of [...pairs.filter(item => item.differs), ...pairs.filter(item => !item.differs)]) {
        // MusicBrainz searches ignore case, so searches that differ only in case are one.
        const key = fold(canonicalQuery(pair.query)!), at = keys.indexOf(key);
        if (at >= 0) { if (!bridge[at].itemKeys.includes(pair.itemKey)) bridge[at] = { ...bridge[at], itemKeys: [...bridge[at].itemKeys, pair.itemKey] }; continue; }
        if (bridge.length >= JOB.bridgeSearches) { unbridged.add(pair.itemKey); continue; }
        keys.push(key); bridge.push({ ...pair.query, itemKeys: [pair.itemKey] });
    }
    return { ...stage, items: stage.items.map(item => unbridged.has(item.key) ? { ...item, unbridged: true as const } : item),
        bridge, bridgeIndex: 0, bridgeOutcomes: bridge.map(() => 'unsent' as const) };
}

/** Stores the outcome of bridge search `index`: it found a release, found none, or was refused before anything was sent. */
export function recordBridgeAnswer(stage: LookupItunesStage, index: number, outcome: 'found' | 'none' | 'refused'): LookupItunesStage {
    if (!stage.bridge || index !== stage.bridgeIndex || index >= stage.bridge.length) return stage;
    return { ...stage, bridgeIndex: index + 1, bridgeOutcomes: stage.bridgeOutcomes.map((value, at) => at === index ? outcome : value) };
}

/**
 * Ends the bridge: a result is `found` when one of its searches found a MusicBrainz release (evidence only), `unavailable` when
 * MusicBrainz was exhausted before one of its searches could run, `notRun` when one was refused, could not be built or was over the
 * bound, and `noRelease` when every search answered none. Every result not found needs its collection lookup, once per collection.
 */
export function finishItunesBridge(stage: LookupItunesStage, musicBrainzExhausted: boolean): LookupItunesStage {
    if (stage.finalized) return stage;
    const bridge = stage.bridge ?? [], pending = new Set<string>();
    const items = stage.items.map((item): LookupItunesItem => {
        const outcomes = bridge.flatMap((query, at) => query.itemKeys.includes(item.key) ? [stage.bridgeOutcomes[at] ?? 'unsent'] : []);
        const gap = item.unbridged === true || !outcomes.length || outcomes.includes('unsent');
        const state: LookupItunesItem['bridge'] = outcomes.includes('found') ? 'found' : musicBrainzExhausted && gap ? 'unavailable'
            : gap || outcomes.includes('refused') ? 'notRun' : 'noRelease';
        if (state === 'found') return { ...item, bridge: state, collection: 'notNeeded' };
        const repeat = pending.has(item.collectionId);
        pending.add(item.collectionId);
        return { ...item, bridge: state, collection: repeat ? 'notNeeded' : 'pending' };
    });
    return { ...stage, items, bridgeIndex: bridge.length, finalized: true };
}

/**
 * The stage's next search-side request (iTunes requests, then the bridge planned once, then each bridge search), or null when
 * none is left. With MusicBrainz exhausted, the remaining bridge searches are never sent.
 */
export function nextItunesSearchAction(stage: LookupItunesStage, musicBrainzExhausted: boolean): { stage: LookupItunesStage; action: LookupItunesAction | null } {
    if (stage.state === 'running' && stage.requestIndex < stage.requests.length) {
        return { stage, action: { kind: 'itunes', index: stage.requestIndex, request: stage.requests[stage.requestIndex] } };
    }
    let next: LookupItunesStage = stage.state === 'running' ? { ...stage, state: 'answered' } : stage;
    if (next.finalized) return { stage: next, action: null };
    next = planItunesBridge(next, musicBrainzExhausted);
    const bridge = next.bridge ?? [];
    if (!musicBrainzExhausted && next.bridgeIndex < bridge.length) {
        const { itemKeys: _itemKeys, ...query } = bridge[next.bridgeIndex];
        return { stage: next, action: { kind: 'bridge', index: next.bridgeIndex, query: query as PlannedLookupQuery } };
    }
    return { stage: next, action: null };
}

/**
 * After the bridge and the bridged releases' details: ends the bridge, then the next collection lookup (in the result's first
 * storefront). A result the candidate bound, or the `itunesCollectionLookups` bound (counting every result whose lookup has an
 * outcome), would leave out is skipped without a request, making the stage incomplete.
 */
export function nextItunesCollectionAction(stage: LookupItunesStage, candidateCount: number, musicBrainzExhausted: boolean): { stage: LookupItunesStage; action: LookupItunesAction | null } {
    let next = finishItunesBridge(stage, musicBrainzExhausted);
    const item = next.items.find(entry => entry.collection === 'pending');
    if (!item) return { stage: next, action: null };
    const looked = next.items.filter(entry => entry.collection !== 'notNeeded' && entry.collection !== 'pending').length;
    if (next.state === 'unavailable' || candidateCount >= JOB.candidates || looked >= JOB.itunesCollectionLookups) {
        next = { ...next, complete: false, items: next.items.map(entry => entry.collection === 'pending' ? { ...entry, collection: next.state === 'unavailable' ? 'failed' : 'skipped' } : entry) };
        return { stage: next, action: null };
    }
    return { stage: next, action: { kind: 'itunesCollection', itemKey: item.key, collectionId: item.collectionId, storefront: item.names[0].storefront } };
}

/** Records a collection lookup's outcome on its pending result; `skipped` and `failed` leave a plausible result out (incomplete). */
export function recordItunesCollection(stage: LookupItunesStage, itemKey: string, outcome: 'fetched' | 'missing' | 'failed' | 'skipped'): LookupItunesStage {
    if (!stage.items.some(item => item.key === itemKey && item.collection === 'pending')) return stage;
    return { ...stage, complete: stage.complete && (outcome === 'fetched' || outcome === 'missing'),
        items: stage.items.map(item => item.key === itemKey && item.collection === 'pending' ? { ...item, collection: outcome } : item) };
}

/**
 * iTunes stayed unavailable through its automatic retries: nothing more is sent to it, and the run continues with what it has (the
 * view reports iTunes unavailable). A result left without its collection lookup makes the stage incomplete; skipped searches do not.
 */
export function itunesUnavailable(stage: LookupItunesStage): LookupItunesStage {
    const left = stage.items.some(item => item.collection === 'pending');
    return { ...stage, state: 'unavailable', requestIndex: stage.requests.length, complete: stage.complete && !left,
        items: stage.items.map(item => item.collection === 'pending' ? { ...item, collection: 'failed' } : item) };
}

const positive = (value: number | null) => value !== null && Number.isSafeInteger(value) && value > 0 ? value : null;
/**
 * The values of an iTunes collection in the release shape candidates store: the collection name as given, its single artist string
 * as one primary entry without a MusicBrainz ID (never split), no label or country, the iTunes date at day precision as the
 * release's own date (no first-release date), the barcode only when a UPC lookup found it, media by disc number with tracks in
 * track-number order and durations in milliseconds, each track credited with its song's single artist string as one entry
 * (never split), and front artwork only for an allowlisted artwork address.
 */
export function itunesRelease(collection: ItunesCollection, songs: readonly ItunesTrack[], barcode: string | null): MusicBrainzRelease {
    const discs = new Map<number, { song: ItunesTrack; order: number }[]>();
    songs.forEach((song, order) => { const disc = positive(song.discNumber) ?? 1; discs.set(disc, [...discs.get(disc) ?? [], { song, order }]); });
    const media = [...discs.entries()].sort(([left], [right]) => left - right).map(([position, list]) => ({
        position, format: null,
        tracks: [...list].sort((left, right) => (positive(left.song.trackNumber) ?? Number.MAX_SAFE_INTEGER) - (positive(right.song.trackNumber) ?? Number.MAX_SAFE_INTEGER) || left.order - right.order)
            .map(({ song }, index): MusicBrainzTrack => {
                const number = positive(song.trackNumber) ?? index + 1;
                return { position: number, number: String(number), title: song.trackName, lengthMs: positive(song.trackTimeMillis), recordingId: '', isrcs: [],
                    artistCredit: [{ name: song.artistName, joinPhrase: '', artistId: '', artistName: song.artistName }] };
            })
    }));
    const upc = normalizeGtin(barcode)?.digits ?? null;
    return {
        releaseId: collection.collectionId, releaseGroupId: null, title: collection.collectionName, status: null,
        artistCredit: [{ name: collection.artistName, joinPhrase: '', artistId: '', artistName: collection.artistName }], labels: [],
        barcode: upc, barcodeText: upc, country: null, date: collection.releaseDate, primaryType: null, secondaryTypes: [], trackCount: songs.length,
        groupFirstReleaseDate: null, media, frontArtwork: itunesArtworkUrl(collection.artworkUrl, 1200) !== null
    };
}

/**
 * The iTunes-only candidate a collection lookup gives for a result not found in MusicBrainz, or null when the answer lacks that
 * collection or its songs (the song results' own collection names are never used). Its key and release ID are the collection ID.
 * An answer with fewer songs than the collection's track count (songs that storefront does not offer), or one the lookup limit
 * may have cut off when no track count is given, is no complete release: the candidate keeps no release (`omitted`, so it is
 * incomplete and unranked) and records the reported track count, so a comparison it could match stays partial.
 */
export function itunesCandidate(item: LookupItunesItem, result: ItunesSearchResult | null): StoredLookupCandidate | null {
    const check = item.bridge === 'noRelease' || item.bridge === 'unavailable' || item.bridge === 'notRun' ? item.bridge : null;
    const collection = result?.collections.find(entry => entry.collectionId === item.collectionId);
    const songs = result?.tracks.filter(song => song.collectionId === item.collectionId) ?? [];
    if (!check || !collection || !songs.length || !normalizeItunesId(collection.collectionId)) return null;
    const base = { key: `itunes:${collection.collectionId}`, source: 'itunes' as const, releaseId: collection.collectionId, basis: 'itunes' as const, summary: null,
        itunes: { storefront: item.names[0].storefront, artworkUrl: itunesArtworkAddress(collection.artworkUrl), check } };
    // The answer's one collection result takes a place within the lookup limit beside its songs.
    const reported = positive(collection.trackCount);
    const short = reported !== null ? songs.length < reported : songs.length >= METADATA_LOOKUP_LIMITS.itunesLookupLimit - 1;
    if (short) return { ...base, release: null, details: 'omitted', ...(reported !== null ? { reportedTrackCount: reported } : {}) };
    return { ...base, release: itunesRelease(collection, songs, item.barcode), details: 'fetched' };
}

/**
 * The localized artist names a run's iTunes results showed: per result, its distinct (case-folded) artist names across storefronts,
 * kept when there are at least two (at most `localizedNames` of at most 200 characters, without control or invisible characters),
 * at most `localizedGroups` distinct groups. A record without a stage, or a malformed one, gives none.
 */
export function lookupLocalizedGroups(record: Pick<MetadataLookupRecord, 'itunesStage'> | null | undefined): string[][] {
    const stage = storedItunesStage(record?.itunesStage), groups: string[][] = [], seen = new Set<string>();
    for (const item of stage?.items ?? []) {
        const names: string[] = [];
        for (const { artist } of item.names) {
            const name = artist.normalize('NFC').trim();
            if (name && name.length <= 200 && !/[\p{Cc}\p{Cf}\p{Cs}]/u.test(name) && !isPlaceholderCredit(name) && !names.some(known => fold(known) === fold(name))) names.push(name);
        }
        const key = JSON.stringify(names.map(fold).sort());
        if (names.length < 2 || seen.has(key) || groups.length >= JOB.localizedGroups) continue;
        seen.add(key); groups.push(names.slice(0, JOB.localizedNames));
    }
    return groups;
}
